func.func @main(%a: tensor<7x6xf32>, %b: tensor<7x4xf32>) -> tensor<6x4xf32> {
  // We want out[i, j] = sum_k a[k, i] * b[k, j]
  // That is, (transpose(a) @ b), where transpose(a) is (6x7), b is (7x4)
  // But a is (7x6), so we need to swap axes 0 and 1 for a.
  %a_t = "stablehlo.transpose"(%a) {permutation = array<i64: 1, 0>} : (tensor<7x6xf32>) -> tensor<6x7xf32>
  // Now do dot_general: (6x7) @ (7x4) -> (6x4)
  %out = "stablehlo.dot_general"(%a_t, %b) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<6x7xf32>, tensor<7x4xf32>) -> tensor<6x4xf32>
  return %out : tensor<6x4xf32>
}

func.func @main(
    %conv_weight: tensor<16x3x4x4x4xf32>,   // [out_c, in_c, kD, kH, kW]
    %conv_bias: tensor<16xf32>,             // [out_c]
    %gn_weight: tensor<16xf32>,             // [out_c]
    %gn_bias: tensor<16xf32>,               // [out_c]
    %input: tensor<6x3x16x7x7xf32>          // [B, in_c, D, H, W]
  ) -> tensor<6x16xf32> {
    // 1. Conv3D
    // PyTorch: input [B, C, D, H, W], weight [out_c, in_c, kD, kH, kW]
    // StableHLO: input [B, C, D, H, W], weight [O, I, kD, kH, kW]
    // Output: [B, O, D_out, H_out, W_out]
    %conv = "stablehlo.convolution"(%input, %conv_weight) {
      window_strides = array<i64: 1, 1, 1>,
      padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1, 1, 1>,
      rhs_dilation = array<i64: 1, 1, 1>,
      dimension_numbers = #stablehlo.conv<[
        b, f, 0, 1, 2
      ]x[
        o, i, 0, 1, 2
      ]->[
        b, o, 0, 1, 2
      ]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x3x16x7x7xf32>, tensor<16x3x4x4x4xf32>) -> tensor<6x16x13x4x4xf32>

    // Add bias: bias shape [16], need to broadcast to [6,16,13,4,4]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%conv_bias) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<16xf32>) -> tensor<6x16x13x4x4xf32>
    %conv_bias = "stablehlo.add"(%conv, %bias_bcast) : (tensor<6x16x13x4x4xf32>, tensor<6x16x13x4x4xf32>) -> tensor<6x16x13x4x4xf32>

    // 2. HardSwish activation: x * relu6(x + 3) / 6
    // relu6(x) = min(max(x, 0), 6)
    // Compute x + 3
    %cst_3 = "stablehlo.constant"() {value = dense<3.0> : tensor<f32>} : () -> tensor<f32>
    %cst_3_bcast = "stablehlo.broadcast_in_dim"(%cst_3) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x16x13x4x4xf32>
    %x_plus_3 = "stablehlo.add"(%conv_bias, %cst_3_bcast) : (tensor<6x16x13x4x4xf32>, tensor<6x16x13x4x4xf32>) -> tensor<6x16x13x4x4xf32>
    // max(x+3, 0)
    %cst_0 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %cst_0_bcast = "stablehlo.broadcast_in_dim"(%cst_0) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x16x13x4x4xf32>
    %relu6_lo = "stablehlo.maximum"(%x_plus_3, %cst_0_bcast) : (tensor<6x16x13x4x4xf32>, tensor<6x16x13x4x4xf32>) -> tensor<6x16x13x4x4xf32>
    // min(..., 6)
    %cst_6 = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
    %cst_6_bcast = "stablehlo.broadcast_in_dim"(%cst_6) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x16x13x4x4xf32>
    %relu6 = "stablehlo.minimum"(%relu6_lo, %cst_6_bcast) : (tensor<6x16x13x4x4xf32>, tensor<6x16x13x4x4xf32>) -> tensor<6x16x13x4x4xf32>
    // x * relu6 / 6
    %mul = "stablehlo.multiply"(%conv_bias, %relu6) : (tensor<6x16x13x4x4xf32>, tensor<6x16x13x4x4xf32>) -> tensor<6x16x13x4x4xf32>
    %cst_6_div = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
    %cst_6_div_bcast = "stablehlo.broadcast_in_dim"(%cst_6_div) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x16x13x4x4xf32>
    %hardswish = "stablehlo.divide"(%mul, %cst_6_div_bcast) : (tensor<6x16x13x4x4xf32>, tensor<6x16x13x4x4xf32>) -> tensor<6x16x13x4x4xf32>

    // 3. GroupNorm (num_groups=4, num_channels=16)
    // GroupNorm: for each group of 4 channels, normalize over [C//G, D, H, W] per batch
    // Reshape to [B, G, C_per_G, D, H, W] = [6, 4, 4, 13, 4, 4]
    %gn_reshaped = "stablehlo.reshape"(%hardswish) : (tensor<6x16x13x4x4xf32>) -> tensor<6x4x4x13x4x4xf32>
    // Compute mean over [2,3,4,5] (C_per_G, D, H, W)
    %cst_zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %mean = "stablehlo.reduce"(%gn_reshaped, %cst_zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 2,3,4,5>} : (tensor<6x4x4x13x4x4xf32>, tensor<f32>) -> tensor<6x4xf32>
    // Count of elements per group: 4*13*4*4 = 832
    %cst_832 = "stablehlo.constant"() {value = dense<832.0> : tensor<f32>} : () -> tensor<f32>
    %cst_832_bcast = "stablehlo.broadcast_in_dim"(%cst_832) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x4xf32>
    %mean_norm = "stablehlo.divide"(%mean, %cst_832_bcast) : (tensor<6x4xf32>, tensor<6x4xf32>) -> tensor<6x4xf32>
    // Broadcast mean to [6,4,4,13,4,4]
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_norm) {
      broadcast_dimensions = array<i64: 0,1>
    } : (tensor<6x4xf32>) -> tensor<6x4x4x13x4x4xf32>
    // Subtract mean
    %centered = "stablehlo.subtract"(%gn_reshaped, %mean_bcast) : (tensor<6x4x4x13x4x4xf32>, tensor<6x4x4x13x4x4xf32>) -> tensor<6x4x4x

func.func @main(%u: tensor<3xf32>, %v: tensor<4xf32>) -> tensor<3x4xf32> {
  // Broadcast %u from (3) to (3,4) along dimension 0
  %u_b = "stablehlo.broadcast_in_dim"(%u) {broadcast_dimensions = array<i64: 0>} : (tensor<3xf32>) -> tensor<3x4xf32>
  // Broadcast %v from (4) to (3,4) along dimension 1
  %v_b = "stablehlo.broadcast_in_dim"(%v) {broadcast_dimensions = array<i64: 1>} : (tensor<4xf32>) -> tensor<3x4xf32>
  // Elementwise multiply
  %out = stablehlo.multiply %u_b, %v_b : tensor<3x4xf32>
  return %out : tensor<3x4xf32>
}

module {
  func.func @main(%x: tensor<7x8xf32>) -> tensor<7x8xf32> {
    // Compute exp(x)
    %exp_x = "stablehlo.exponential"(%x) : (tensor<7x8xf32>) -> tensor<7x8xf32>

    // Constant 0.0 for reduce init
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

    // Sum over dimension 1 (axis=1)
    %sum_exp = "stablehlo.reduce"(%exp_x, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<7x8xf32>, tensor<f32>) -> tensor<7xf32>

    // Broadcast sum_exp to shape [7,8]
    %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<7x8xf32>

    // Divide exp(x) by sum_exp_bcast
    %softmax = "stablehlo.divide"(%exp_x, %sum_exp_bcast) : (tensor<7x8xf32>, tensor<7x8xf32>) -> tensor<7x8xf32>

    return %softmax : tensor<7x8xf32>
  }
}

func.func @main(%arg0: tensor<6x6xf32>) -> tensor<6x6xf32> {
  // Cumulative product along dim=1 (the second dimension)
  // We'll use reduce_window with window_dimensions = [1, i+1] for each i, and window_strides = [1,1], padding = [[0,0],[0,0]]
  // But since reduce_window is not cumulative, we simulate cumprod by using a lower-triangular window mask.

  // The trick: For each output[i, j], we want prod_{k=0}^j x[i, k]
  // This can be done by a reduce_window with window_dimensions = [1, j+1], window_strides = [1,1], and taking the last element in the window.
  // But StableHLO's reduce_window applies the same window size everywhere.
  // So, we use a window of size [1, 6] (full along dim=1), and mask out elements after the current column using a lower-triangular mask.

  // Step 1: Create a lower-triangular mask of shape [6,6]
  // mask[i, j] = 1 if j <= i else 0

  // Create a [6] tensor with values 0..5 for rows and columns
  %row_ids = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<6xi32>
  %col_ids = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<6xi32>
  // Broadcast to [6,6]
  %row_ids_b = "stablehlo.broadcast_in_dim"(%row_ids) {broadcast_dimensions = array<i64: 0>} : (tensor<6xi32>) -> tensor<6x6xi32>
  %col_ids_b = "stablehlo.broadcast_in_dim"(%col_ids) {broadcast_dimensions = array<i64: 1>} : (tensor<6xi32>) -> tensor<6x6xi32>
  // mask = row_ids_b >= col_ids_b
  %mask_bool = "stablehlo.compare"(%row_ids_b, %col_ids_b) {comparison_direction = "GE"} : (tensor<6x6xi32>, tensor<6x6xi32>) -> tensor<6x6xi1>
  // Convert mask to f32
  %mask = "stablehlo.convert"(%mask_bool) : (tensor<6x6xi1>) -> tensor<6x6xf32>

  // Step 2: For each row, we want to mask the input so that for position [i, j], only x[i, 0..j] are kept, others are set to 1 (neutral for prod)
  // So, for each row, for each col, mask[i, k] = 1 if k <= col else 0, but we want to apply this mask in a sliding window.
  // Instead, we can use reduce_window with window_dimensions = [1, 6], window_strides = [1,1], padding = [[0,0],[0,0]], and for each output[i, j], the window covers x[i, 0..5], but we multiply by mask[j, k] to zero out elements after j.

  // To do this, we need to, for each output[i, j], compute prod_{k=0}^5 x[i, k]^{mask[j, k]}
  // But since mask[j, k] is 1 for k <= j, 0 otherwise, and x^0 = 1, x^1 = x, so this works.

  // So, for each output[i, j], output[i, j] = prod_{k=0}^5 x[i, k]^{mask[j, k]}

  // To implement this, we need to expand input to [6,6,6], where input[i, k] -> input[i, j, k] for all j, and mask[j, k] is broadcast to [6,6,6]
  // Then, for each i, j, prod over k of input[i, k]^{mask[j, k]}

  // Step 3: Expand input to [6,6,6] and mask to [6,6,6]
  // input[i, k] -> input[i, j, k] (broadcast along j)
  %input_exp = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0,2}} : (tensor<6x6xf32>) -> tensor<6x6x6xf32>
  // mask[j, k] -> mask[j, k] broadcast along i
  %mask_exp = "stablehlo.broadcast_in_dim"(%mask) {broadcast_dimensions = array<i64: 1,2}} : (tensor<6x6xf32>) -> tensor<6x6x6xf32>

  // Step 4: Raise input to the power of mask (x^1 = x, x^0 = 1)
  %input_pow = "stablehlo.power"(%input_exp, %mask_exp) : (tensor<6x6x6xf32>, tensor<6x6x6xf32>) -> tensor<6x6x6xf32>

  // Step 5: Reduce product along k (dimension 2)
  %init = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %cumprod = "stablehlo.reduce"(%input_pow, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %m = stablehlo.multiply %a, %b : tensor<f32>
      stablehlo.return %m : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<6x6x6xf32>, tensor<f32>) -> tensor<6x6xf32>

  // The result is [6,6] with cumprod along dim=1
  return %cumprod : tensor<6x6xf32>
}

func.func @main(
  %arg0: tensor<6x1x1xf32>,      // bias: (6,1,1)
  %arg1: tensor<7x6x4x4xf32>,    // conv_transpose.weight: (in_c, out_c, kH, kW) = (7,6,4,4)
  %arg2: tensor<6xf32>,          // conv_transpose.bias: (6,)
  %arg3: tensor<6x7x7x7xf32>     // input: (N=6, C=7, H=7, W=7)
) -> tensor<6x6x15x15xf32> {
  // 1. ConvTranspose2d (PyTorch): 
  //   in: (N=6, C_in=7, H=7, W=7)
  //   weight: (C_in=7, C_out=6, kH=4, kW=4)
  //   bias: (C_out=6,)
  //   stride=2, padding=1, output_padding=1
  //   output: (N=6, C_out=6, H_out=15, W_out=15)
  //   StableHLO expects:
  //     lhs: (N, C_in, H, W)
  //     rhs: (C_out, C_in, kH, kW)
  //   So, need to transpose weight from (7,6,4,4) to (6,7,4,4)

  // Transpose weight: (7,6,4,4) -> (6,7,4,4)
  %w_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<7x6x4x4xf32>) -> tensor<6x7x4x4xf32>

  // ConvTranspose2d is a "backward" convolution:
  //   - input: (N, C_in, H, W)
  //   - kernel: (C_out, C_in, kH, kW)
  //   - output: (N, C_out, H_out, W_out)
  //   - window_strides = stride
  //   - padding = padding
  //   - output_padding = output_padding
  //   - lhs_dilation = stride
  //   - rhs_dilation = 1
  //   - window_strides = 1
  //   - padding = kernel_size - 1 - padding
  //   - lhs_dilation = stride
  //   - rhs_dilation = 1

  // For ConvTranspose2d, the equivalent in StableHLO is:
  //   - lhs = input
  //   - rhs = weight (transposed)
  //   - window_strides = (1,1)
  //   - padding = (kernel_size - 1 - padding, kernel_size - 1 - padding)
  //   - lhs_dilation = (stride, stride)
  //   - rhs_dilation = (1,1)
  //   - output_shape = computed

  // PyTorch: stride=2, padding=1, output_padding=1, kernel_size=4
  // StableHLO:
  //   - window_strides = (1,1)
  //   - padding = (kernel_size - 1 - padding, kernel_size - 1 - padding) = (4-1-1, 4-1-1) = (2,2)
  //   - lhs_dilation = (2,2)
  //   - rhs_dilation = (1,1)

  // But to get output_padding=1, we need to add extra padding to the output.
  // The formula for output shape:
  //   H_out = (H_in - 1) * stride - 2*padding + kernel_size + output_padding
  //   For H_in=7, stride=2, padding=1, kernel_size=4, output_padding=1:
  //   H_out = (7-1)*2 - 2*1 + 4 + 1 = 6*2 - 2 + 4 + 1 = 12 - 2 + 4 + 1 = 15

  // So, we use:
  //   window_strides = (1,1)
  //   padding = (2,2)
  //   lhs_dilation = (2,2)
  //   rhs_dilation = (1,1)

  // But to get output_padding=1, we need to pad the output by 1 at the end after convolution.

  // Conv dimension_numbers:
  //   input: [b, f, 0, 1] (N, C_in, H, W)
  //   kernel: [o, i, 0, 1] (C_out, C_in, kH, kW)
  //   output: [b, f, 0, 1] (N, C_out, H_out, W_out)

  // Prepare conv bias: (6,) -> (1,6,1,1)
  %conv_bias_reshape = "stablehlo.reshape"(%arg2) : (tensor<6xf32>) -> tensor<1x6x1x1xf32>
  %conv_bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias_reshape) {broadcast_dimensions = array<i64: 1>} : (tensor<1x6x1x1xf32>) -> tensor<6x6x15x15xf32>

  // Perform transposed convolution
  %conv = "stablehlo.convolution"(%arg3, %w_t) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[2,2],[2,2]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x7x7xf32>, tensor<6x7x4x4xf32>) -> tensor<6x6x15x15xf32>

  // Add conv bias
  %conv_plus_bias = "stablehlo.add"(%conv, %conv_bias_broadcast) : (tensor<6x6x15x15xf32>, tensor<6x6x15x15xf32>) -> tensor<6x6x15x15xf32>

  // 2. Softmax along dim=1 (channel dim)
  // For shape (6,6,15,15), softmax along axis=1

  // Compute max for numerical stability
  %neg_inf = "stablehlo.constant"() {value = dense<0xFF800000>} : () -> tensor<f32>
  %max_init = "stablehlo.broadcast_in_dim"(%neg_inf) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x15x15xf32>
  %max = "stablehlo.reduce"(%conv_plus_bias, %neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %m = "stablehlo.maximum"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%m) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x15x15xf32>

  // Subtract max for numerical stability
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0,2,3>} : (tensor<6x15x15xf32>) -> tensor<6x6x15x15xf32>
  %shifted = "stablehlo.subtract"(%conv_plus_bias, %max_broadcast) : (tensor<6x6x15x15xf32>, tensor<6x6x15x15xf32>) -> tensor<6x6x15x15xf32>

  // Exponentiate
  %exp = "stablehlo.exponential"(%shifted) : (tensor<6x6x15x15xf32>) -> tensor<6x6x15x15xf32>

  // Sum along axis=1
  %zero = "stablehlo.constant"() {value = dense<0.0>} : () -> tensor<f32>
  %sum = "stablehlo.reduce"(%exp, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64

module {
  func.func @main(
    %arg0: tensor<6x7x3x3xf32>,   // conv.weight [out_c, in_c, kH, kW]
    %arg1: tensor<6xf32>,         // conv.bias [out_c]
    %arg2: tensor<6x7x6x6xf32>    // input [N, in_c, H, W]
  ) -> tensor<6x6x2x2xf32> {
    // --- Convolution ---
    // PyTorch: out = conv2d(input, weight, bias)
    // input: [N, in_c, H, W] = [6, 7, 6, 6]
    // weight: [out_c, in_c, kH, kW] = [6, 7, 3, 3]
    // bias: [out_c] = [6]
    // output: [N, out_c, H_out, W_out] = [6, 6, 4, 4]
    // Conv params:
    //   stride=1, padding=0, dilation=1, groups=1

    // StableHLO expects:
    //   input: [N, in_c, H, W]
    //   kernel: [out_c, in_c, kH, kW]
    //   output: [N, out_c, H_out, W_out]
    // dimension_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]

    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

    // --- Add bias ---
    // bias: [6] -> broadcast to [6, 6, 4, 4] along dim 1 (out_c)
    // We want to broadcast [6] to [6, 6, 4, 4] along dim 1
    // So broadcast_dimensions = [1]
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<6xf32>) -> tensor<6x6x4x4xf32>

    %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x4x4xf32>

    // --- Subtract subtract1_value (0.5) ---
    %cst_sub1 = stablehlo.constant dense<0.5> : tensor<f32>
    // Broadcast to [6, 6, 4, 4]
    %sub1_broadcast = "stablehlo.broadcast_in_dim"(%cst_sub1) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x6x4x4xf32>

