    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    %bias_bcast_full = "stablehlo.broadcast_in_dim"(%bias_bcast) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>
    %biased = "stablehlo.add"(%conv, %bias_bcast_full) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    // 3. Divide by constant divisor=2
    %cst_two = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
    %two_bcast = "stablehlo.broadcast_in_dim"(%cst_two) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %div = "stablehlo.divide"(%biased, %two_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

