    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %ge_zero = "stablehlo.compare"(%div, %zero_bcast) {
      comparison_direction = #stablehlo<comparison_direction GE>,
      compare_type = #stablehlo<comparison_type FLOAT>
    } : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xi1>
    %neg_slope = "stablehlo.constant"() {value = dense<0.01> : tensor<f32>} : () -> tensor<f32>
    %neg_slope_bcast = "stablehlo.broadcast_in_dim"(%neg_slope) {
      broadcast_dimensions = array<i64: >
    } : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %mul_neg = "stablehlo.multiply"(%div, %neg_slope_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
