module {
  func.func @main(
    %arg0: tensor<7x7xf32>,   // gemm.weight
    %arg1: tensor<7xf32>,     // gemm.bias
    %arg2: tensor<6x7xf32>    // input x
  ) -> tensor<6x1xf32> {
    // GEMM: x @ weight^T + bias
    // %arg2: (6,7), %arg0: (7,7) (weight), %arg1: (7)
    // PyTorch Linear: y = x @ weight^T + bias

    // Transpose weight to (7,7) -> (7,7) (no-op, but for generality)
    // Actually, in PyTorch, weight is (out_features, in_features), so we need to transpose to (in_features, out_features)
    // But here both are 7, so it's a square, but let's transpose anyway.
    %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

    // Dot: (6,7) x (7,7) -> (6,7)
    %gemm = "stablehlo.dot_general"(%arg2, %weight_t) {
      dot_dimension_numbers = #stablehlo.dot<
        lhs_batching_dimensions = [],
        rhs_batching_dimensions = [],
        lhs_contracting_dimensions = [1],
        rhs_contracting_dimensions = [0]
      >
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Broadcast bias (7) to (6,7)
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

    // Add bias
    %x1 = "stablehlo.add"(%gemm, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // torch.max(x, dim=1, keepdim=True): (6,7) -> (6,1)
    // Reduce with maximum along dim=1
    %neg_inf = "stablehlo.constant"() {value = dense<0xFF800000>} : () -> tensor<f32>
    %max = "stablehlo.reduce"(%x1, %neg_inf) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %m = "stablehlo.maximum"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%m) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

    // Expand (6) -> (6,1)
    %max_bcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

    // Subtract mean along dim=1, keepdim=True
    // Compute mean: sum along dim=1, then divide by 7
    %zero = "stablehlo.constant"() {value = dense<0.0>} : () -> tensor<f32>
    %sum = "stablehlo.reduce"(%max_bcast, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
    %sum_bcast = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>
    %seven = "stablehlo.constant"() {value = dense<7.0>} : () -> tensor<f32>
    %seven_bcast = "stablehlo.broadcast_in_dim"(%seven) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
    %mean = "stablehlo.divide"(%sum_bcast, %seven_bcast) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>

    // Subtract mean
    %centered = "stablehlo.subtract"(%max_bcast, %mean) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>

    // GELU: y = 0.5 * x * (1 + erf(x / sqrt(2)))
    %half = "stablehlo.constant"() {value = dense<0.5>} : () -> tensor<f32>
    %one = "stablehlo.constant"() {value = dense<1.0>} : () -> tensor<f32>
    %sqrt2 = "stablehlo.constant"() {value = dense<1.4142135>} : () -> tensor<f32>

    // x / sqrt(2)
    %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
    %div = "stablehlo.divide"(%centered, %sqrt2_bcast) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
    // erf(x / sqrt(2))
    %erf = "chlo.erf"(%div) : (tensor<6x1xf32>) -> tensor<6x1xf32>
    // 1 + erf(...)
    %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
    %add1 = "stablehlo.add"(%one_bcast, %erf) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
    // x * (1 + erf(...))
    %mul1 = "stablehlo.multiply"(%centered, %add1) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
    // 0.5 * ...
    %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
    %gelu = "stablehlo.multiply"(%half_bcast, %mul1) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>

    return %gelu : tensor<6x1xf32>
  }
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // %arg0: weight (7x7)
  // %arg1: input x (6x7)

  // 1. Transpose weight to (7x7) -> (7x7), but PyTorch uses weight.T, so we need (7x7) -> (7x7), which is identity.
  // But for generality, let's transpose anyway.
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // 2. Matrix multiplication: (6x7) @ (7x7) = (6x7)
  %matmul = "stablehlo.dot_general"(%arg1, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // 3. Divide by 2
  %cst_two = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  // Broadcast 2.0 to (6x7)
  %two_broadcast = "stablehlo.broadcast_in_dim"(%cst_two) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %div = "stablehlo.divide"(%matmul, %two_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // 4. Sum over dim=1 (columns), keepdim=True → output shape (6x1)
  %cst_zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %sum = "stablehlo.reduce"(%div, %cst_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  // 5. Multiply by scaling_factor=1.5
  %cst_sf = "stablehlo.constant"() {value = dense<1.5> : tensor<f32>} : () -> tensor<f32>
  // Broadcast 1.5 to (6x1)
  %sf_broadcast = "stablehlo.broadcast_in_dim"(%cst_sf) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1xf32>
  %scaled = "stablehlo.multiply"(%sum, %sf_broadcast) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>

  return %scaled : tensor<6x1xf32>
}

func.func @main(%a: tensor<7x6xf32>, %b: tensor<7x5xf32>) -> tensor<6x5xf32> {
