  // Select: if mask then x else 0.0
  %out = "stablehlo.select"(%mask, %x, %zero) : (tensor<3x3xi1>, tensor<3x3xf32>, tensor<3x3xf32>) -> tensor<3x3xf32>
  return %out : tensor<3x3xf32>
