    %exp_x = "stablehlo.exponential"(%x) : (tensor<4x8xf32>) -> tensor<4x8xf32>

    // Create a zero constant for reduce init
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

