func.func @main(
  %arg0: tensor<6x1x1xf32>,      // multiplier
  %arg1: tensor<6x6x3x3xf32>,    // conv.weight
  %arg2: tensor<6xf32>,          // conv.bias
  %arg3: tensor<6x6x7x7xf32>     // input
) -> tensor<6x6x5x5xf32> {
  // --- Convolution ---
  // %conv = conv2d(%arg3, %arg1) + %arg2
  // Input:  (N=6, C=6, H=7, W=7)
  // Weight: (O=6, I=6, KH=3, KW=3)
  // Output: (N=6, O=6, H_out=5, W_out=5)
  // PyTorch: NCHW, StableHLO: [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]
  // Stride=1, Padding=0, Dilation=1

  %0 = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<6x6x5x5xf32>

  // --- Add bias ---
  // Bias shape: (6,) -> broadcast to (6,6,5,5) along dim 1 (output channel)
  %1 = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<6xf32>) -> tensor<6x6x5x5xf32>
  %2 = stablehlo.add %0, %1 : tensor<6x6x5x5xf32>

  // --- Multiply by multiplier ---
  // multiplier shape: (6,1,1) -> broadcast to (6,6,5,5) along dim 1 (output channel)
  %3 = "stablehlo.broadcast_in_dim"(%arg0) {
    broadcast_dimensions = array<i64: 1, 2, 3>
  } : (tensor<6x1x1xf32>) -> tensor<6x6x5x5xf32>
  %4 = stablehlo.multiply %2, %3 : tensor<6x6x5x5xf32>

  // --- LeakyReLU(x) = max(x, 0.01 * x) ---
  %c_leaky = stablehlo.constant dense<0.01> : tensor<f32>
  %5 = "stablehlo.broadcast_in_dim"(%c_leaky) {
    broadcast_dimensions = array<i64: >
  } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %6 = stablehlo.multiply %4, %5 : tensor<6x6x5x5xf32>
  %7 = "stablehlo.maximum"(%4, %6) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // --- GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2))) ---
  %c_half = stablehlo.constant dense<0.5> : tensor<f32>
  %c_one = stablehlo.constant dense<1.0> : tensor<f32>
  %c_sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32> // sqrt(2)
  // x / sqrt(2)
  %8 = "stablehlo.broadcast_in_dim"(%c_sqrt2) {
    broadcast_dimensions = array<i64: >
  } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %9 = stablehlo.divide %7, %8 : tensor<6x6x5x5xf32>
  // erf(x / sqrt(2))
  %10 = "chlo.erf"(%9) : (tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>
  // 1 + erf(...)
  %11 = "stablehlo.broadcast_in_dim"(%c_one) {
    broadcast_dimensions = array<i64: >
  } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %12 = stablehlo.add %11, %10 : tensor<6x6x5x5xf32>
  // x * (1 + erf(...))
  %13 = stablehlo.multiply %7, %12 : tensor<6x6x5x5xf32>
  // 0.5 * x * (1 + erf(...))
  %14 = "stablehlo.broadcast_in_dim"(%c_half) {
    broadcast_dimensions = array<i64: >
  } : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %15 = stablehlo.multiply %14, %13 : tensor<6x6x5x5xf32>

  return %15 : tensor<6x6x5x5xf32>
}

func.func @main(
    %bias: tensor<16xf32>,                // arg0: bias (added after Swish)
    %matmul_weight: tensor<16x16xf32>,    // arg1: matmul.weight (out_features x in_features)
    %matmul_bias: tensor<16xf32>,         // arg2: matmul.bias (out_features)
    %gn_weight: tensor<16xf32>,           // arg3: group_norm.weight (out_features)
    %gn_bias: tensor<16xf32>,             // arg4: group_norm.bias (out_features)
    %x: tensor<16x16xf32>                 // arg5: input (batch_size x in_features)
  ) -> tensor<16x16xf32> {
    // Matmul: y = x @ matmul_weight^T + matmul_bias
    // x: [16,16], matmul_weight: [16,16] (out_features x in_features)
    // PyTorch Linear: y = x @ W^T + b
    // So we need to transpose matmul_weight to [16,16] (in_features x out_features)
    // But since both are 16x16, transpose is a no-op, but let's do it for clarity.

    %matmul_weight_t = "stablehlo.transpose"(%matmul_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // Dot: [16,16] x [16,16] -> [16,16]
