      dot_dimension_numbers = #stablehlo.dot<
        lhs_batching_dimensions = [],
        rhs_batching_dimensions = [],
        lhs_contracting_dimensions = [1],
        rhs_contracting_dimensions = [0]
      >
    } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Add matmul_bias: [16] -> [16,16] (broadcast on axis 1)
    %matmul_bias_bcast = "stablehlo.broadcast_in_dim"(%matmul_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %matmul_out_bias = "stablehlo.add"(%matmul_out, %matmul_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Swish: x * sigmoid(x)
    // sigmoid(x) = 1 / (1 + exp(-x))
