    %neg_matmul = "stablehlo.negate"(%matmul_out_bias) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %exp_neg = "stablehlo.exponential"(%neg_matmul) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %exp_neg_plus1 = "stablehlo.add"(%exp_neg, %one) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    %sigmoid = "stablehlo.divide"(%one, %exp_neg_plus1) : (tensor<f32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %swish = "stablehlo.multiply"(%matmul_out_bias, %sigmoid) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Add bias: [16] -> [16,16] (broadcast on axis 1)
    %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %swish_bias = "stablehlo.add"(%swish, %bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // GroupNorm: num_groups=16, num_channels=16, input shape [16,16]
    // Each group is size 1 (since 16/16=1), so normalization is per channel.
    // For each channel (axis 1), compute mean/var over axis 0 (batch).
    // mean: reduce over axis 0 -> shape [16]
    %mean_init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %mean = "stablehlo.reduce"(%swish_bias, %mean_init) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
    %inv_batch = "stablehlo.constant"() {value = dense<0.0625> : tensor<f32>} : () -> tensor<f32> // 1/16
    %mean = "stablehlo.multiply"(%mean, %inv_batch) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

    // Variance: mean((x - mean)^2) over axis 0
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
