    %centered2 = "stablehlo.multiply"(%centered, %centered) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %var_init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %var = "stablehlo.reduce"(%centered2, %var_init) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
