    // Apply group_norm.weight and group_norm.bias: [16] -> [16,16] (broadcast on axis 1)
    %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%gn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %normed_scaled = "stablehlo.multiply"(%normed, %gn_weight_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
