  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<5x5xf32>} : () -> tensor<5x5xf32>
  // Select: if mask, take x, else 0.0
  %out = "stablehlo.select"(%mask, %x, %zero) : (tensor<5x5xi1>, tensor<5x5xf32>, tensor<5x5xf32>) -> tensor<5x5xf32>
  return %out : tensor<5x5xf32>
