func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Linear: y = x @ W^T + b
  // %arg2: x, shape [6,7]
  // %arg0: weight, shape [7,7] (PyTorch: out_features x in_features)
  // %arg1: bias, shape [7]
  // We need to do: dot_general(x, weight, contracting on in_features), then add bias

  // Transpose weight to [in_features, out_features] = [7,7] -> [7,7] (but it's square, so transpose is identity)
  // But PyTorch expects x @ W^T, so we need to transpose weight

  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // Dot: [6,7] x [7,7] -> [6,7]
  %linear = "stablehlo.dot_general"(%arg2, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Broadcast bias [7] to [6,7]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Add bias
  %biased = "stablehlo.add"(%linear, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // ReLU: max(x, 0)
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %relu = "stablehlo.maximum"(%biased, %zero_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Divide by 2.0
  %two = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  %two_bcast = "stablehlo.broadcast_in_dim"(%two) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %out = "stablehlo.divide"(%relu, %two_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  return %out : tensor<6x7xf32>
}

