  %x_bcast = "stablehlo.broadcast_in_dim"(%x) {broadcast_dimensions = array<i64: 0,2>} : (tensor<3x5xf32>) -> tensor<3x6x5xf32>
  // Broadcast %y from [6,5] to [3,6,5] along dims [1,2]
  %y_bcast = "stablehlo.broadcast_in_dim"(%y) {broadcast_dimensions = array<i64: 1,2>} : (tensor<6x5xf32>) -> tensor<3x6x5xf32>
