  %cst_p1 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %8 = "stablehlo.broadcast_in_dim"(%cst_m1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %9 = "stablehlo.broadcast_in_dim"(%cst_p1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %10 = stablehlo.maximum %7, %8 : tensor<6x7xf32>
  %11 = stablehlo.minimum %10, %9 : tensor<6x7xf32>
  // Tanh activation
  %12 = "stablehlo.tanh"(%11) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  // Clamp again between -1.0 and 1.0
  %13 = stablehlo.maximum %12, %8 : tensor<6x7xf32>
  %14 = stablehlo.minimum %13, %9 : tensor<6x7xf32>
  return %14 : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear: y = x @ W^T + b
  // %arg2: (6,7) input
  // %arg0: (7,7) weight
  // %arg1: (7) bias

  // Transpose weight to (7,7) -> (7,7) (no-op, but for generality, let's transpose 0,1)
  %0 = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // Actually, since weight is (out_features, in_features) in PyTorch, and input is (batch, in_features),
  // and torch.nn.Linear does x @ W^T + b, so we need to do dot_general with contracting dim 1 of input and 1 of weight^T.

  // But since weight is (7,7), input is (6,7), we want (6,7) x (7,7) -> (6,7)
  // So, dot_general: lhs: (6,7), rhs: (7,7), contract lhs dim 1, rhs dim 0
  %1 = "stablehlo.dot_general"(%arg2, %arg0) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: bias is (7,), need to broadcast to (6,7)
  %2 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %3 = "stablehlo.add"(%1, %2) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  // Compute -x
  %4 = "stablehlo.negate"(%3) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  // exp(-x)
  %5 = "stablehlo.exponential"(%4) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  // 1 + exp(-x)
  %cst1 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %6 = "stablehlo.broadcast_in_dim"(%cst1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %7 = "stablehlo.add"(%6, %5) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // 1 / (1 + exp(-x))
  %8 = "stablehlo.divide"(%6, %7) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Sum along dim=1, keepdim=True: (6,7) -> (6,1)
  %cst0 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %9 = "stablehlo.reduce"(%8, %cst0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  return %9 : tensor<6x1xf32>
}

func.func @main(%x: tensor<4x5xf32>, %y: tensor<2x5xf32>) -> tensor<4x2xf32> {
  // Broadcast %x from [4,5] to [4,2,5] along dims [0,2]
  %x_b = "stablehlo.broadcast_in_dim"(%x) {broadcast_dimensions = array<i64: 0,2>} : (tensor<4x5xf32>) -> tensor<4x2x5xf32>
  // Broadcast %y from [2,5] to [4,2,5] along dims [1,2]
  %y_b = "stablehlo.broadcast_in_dim"(%y) {broadcast_dimensions = array<i64: 1,2>} : (tensor<2x5xf32>) -> tensor<4x2x5xf32>
  // Subtract: [4,2,5]
  %diff = "stablehlo.subtract"(%x_b, %y_b) : (tensor<4x2x5xf32>, tensor<4x2x5xf32>) -> tensor<4x2x5xf32>
  // Square: [4,2,5]
  %sq = "stablehlo.multiply"(%diff, %diff) : (tensor<4x2x5xf32>, tensor<4x2x5xf32>) -> tensor<4x2x5xf32>
  // Constant zero for reduction
