func.func @main(%arg0: tensor<6x7x8xf32>) -> tensor<6x8xi64> {
  // Create an iota for indices along dim=1 (size 7), shape [6,7,8], iota along dim=1
  %iota = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<6x7x8xi64>

  // Create +inf constant for f32, shape [6,8] (init for min reduction)
  %plus_inf = "stablehlo.constant"() {value = dense<0x7F800000> : tensor<f32>} : () -> tensor<f32>
  // Broadcast to [6,8] for reduction init
