  // Create 0 constant for i64, shape [6,8] (init for argmin index reduction)
  %zero_i64 = "stablehlo.constant"() {value = dense<0> : tensor<i64>} : () -> tensor<i64>
  %zero_i64_bcast = "stablehlo.broadcast_in_dim"(%zero_i64) {broadcast_dimensions = array<i64: >} : (tensor<i64>) -> tensor<6x8xi64>

  // Reduce over dim=1 (the 7-dim), keeping min value and its index
  %result = "stablehlo.reduce"(%arg0, %iota, %plus_inf_bcast, %zero_i64_bcast) ({
    ^bb0(%val: tensor<f32>, %idx: tensor<i64>, %cur_min: tensor<f32>, %cur_arg: tensor<i64>):
      // Compare: is val < cur_min?
      %is_lt = "stablehlo.compare"(%val, %cur_min) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<f32>, tensor<f32>) -> tensor<i1>
      // Select new min value
      %new_min = "stablehlo.select"(%is_lt, %val, %cur_min) : (tensor<i1>, tensor<f32>, tensor<f32>) -> tensor<f32>
      // Select new argmin index
      %new_arg = "stablehlo.select"(%is_lt, %idx, %cur_arg) : (tensor<i1>, tensor<i64>, tensor<i64>) -> tensor<i64>
      "stablehlo.return"(%new_min, %new_arg) : (tensor<f32>, tensor<i64>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x8xf32>, tensor<6x7x8xi64>, tensor<6x8xf32>, tensor<6x8xi64>) -> (tensor<6x8xf32>, tensor<6x8xi64>)

  // The second result is the argmin indices
  %argmin = "stablehlo.get_tuple_element"(%result) {index = 1 : i32} : ((tensor<6x8xf32>, tensor<6x8xi64>)) -> tensor<6x8xi64>
  return %argmin : tensor<6x8xi64>
}

