func.func @main(
  %arg0: tensor<7x16x3x3xf32>,   // conv.weight [out_c, in_c, kh, kw]
  %arg1: tensor<7xf32>,          // conv.bias   [out_c]
  %arg2: tensor<6x16x8x8xf32>    // input       [N, in_c, H, W]
) -> tensor<6x1x6x6xf32> {
  // 1. Convolution
  // PyTorch: input[N, C_in, H, W], weight[C_out, C_in, kH, kW]
  // StableHLO: input [N, C_in, H, W], kernel [C_out, C_in, kH, kW]
  // Output: [N, C_out, H_out, W_out]
  // H_out = floor((H + 2*padding - dilation*(kH-1) - 1)/stride + 1)
  // For kernel_size=3, stride=1, dilation=1, padding=0: H_out = 8-3+1=6

  // Convolution attributes
  // window_strides = [1, 1]
  // padding = [[0, 0], [0, 0]]
  // lhs_dilation = [1, 1]
  // rhs_dilation = [1, 1]
  // dimension_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, o, 0, 1]
  // feature_group_count = 1
  // batch_group_count = 1

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, o, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x16x8x8xf32>, tensor<7x16x3x3xf32>) -> tensor<6x7x6x6xf32>

  // 2. Add bias: bias shape [7], need to broadcast to [6,7,6,6]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x6x6xf32>

  %conv_bias = "stablehlo.add"(%conv, %bias_bcast) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // 3. Reduce-min along channel dimension (dim=1), keepdim=True
  // Reduce shape: [6,7,6,6] -> [6,1,6,6]
  // Identity for min: +inf
  %cst_inf = "stablehlo.constant"() {value = dense<0x7F800000>} : () -> tensor<f32>
  %min = "stablehlo.reduce"(%conv_bias, %cst_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %m = "stablehlo.minimum"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%m) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x1x6x6xf32>

  // 4. Tanh
  %tanh1 = "stablehlo.tanh"(%min) : (tensor<6x1x6x6xf32>) -> tensor<6x1x6x6xf32>
  // 5. Tanh again
  %tanh2 = "stablehlo.tanh"(%tanh1) : (tensor<6x1x6x6xf32>) -> tensor<6x1x6x6xf32>

  return %tanh2 : tensor<6x1x6x6xf32>
}

module {
  // Implements PyTorch nn.ConvTranspose2d with:
  // in_channels=6, out_channels=6, kernel_size=3, stride=1, padding=0, output_padding=0, groups=1, bias=False
  // Input:  %arg1: tensor<8x6x7x7xf32>  (N, C_in, H, W)
  // Weight: %arg0: tensor<6x6x3x3xf32>  (C_in, C_out, KH, KW)  (PyTorch)
  // Output: tensor<8x6x9x9xf32>         (N, C_out, H_out, W_out)
  // 
  // StableHLO expects weights as (C_out, C_in, KH, KW), so we need to swap axes 0 and 1.
  // For transposed convolution, we reverse the spatial dims of the kernel.
  // Then, use stablehlo.convolution with:
  //   - lhs = input (N, C_in, H, W)
  //   - rhs = weight (C_out, C_in, KH, KW)
  //   - window_strides = [1, 1]
  //   - padding = [[2, 2], [2, 2]] (see below)
  //   - lhs_dilation = [1, 1]
  //   - rhs_dilation = [1, 1]
  //   - dimension_numbers = [b, f, 0, 1]x[f, o, 0, 1]->[b, o, 0, 1]
  //   - feature_group_count = 1

  func.func @main(%arg0: tensor<6x6x3x3xf32>, %arg1: tensor<8x6x7x7xf32>) -> tensor<8x6x9x9xf32> {
    // Step 1: Transpose weight from (6,6,3,3) [C_in, C_out, KH, KW] to (6,6,3,3) [C_out, C_in, KH, KW]
    // This is a swap of axes 0 and 1.
    %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>
    // Step 2: Reverse spatial dims (KH, KW) for transposed convolution
    %weight_rev = "stablehlo.reverse"(%weight_t) {dimensions = array<i64: 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>
    // Step 3: Convolution
    //   input:  %arg1: (8,6,7,7) [N, C_in, H, W]
    //   kernel: %weight_rev: (6,6,3,3) [C_out, C_in, KH, KW]
    //   output: (8,6,9,9) [N, C_out, H_out, W_out]
    //   window_strides: [1,1] (from stride=1)
    //   padding: [[2,2],[2,2]] (from formula for transposed conv: pad = kernel_size-1-padding = 2)
    //   lhs_dilation: [1,1]
    //   rhs_dilation: [1,1]
    //   dimension_numbers: [b, f, 0, 1]x[f, o, 0, 1]->[b, o, 0, 1]
    //   feature_group_count: 1
    %result = "stablehlo.convolution"(%arg1, %weight_rev) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[2, 2], [2, 2]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[f, o, 0, 1]->[b, o, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<8x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<8x6x9x9xf32>
    return %result : tensor<8x6x9x9xf32>
  }
}

func.func @main(%arg0: tensor<6x16x3x3xf32>, %arg1: tensor<16x16x7x7xf32>) -> tensor<16x6x5x5xf32> {
