  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  // Add bias
  %linear_bias = "stablehlo.add"(%linear, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Broadcast constant [scalar] to [6,7]
  %const_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>

