func.func @main(
  %arg0: tensor<6xf32>,      // bn.weight (gamma)
  %arg1: tensor<6xf32>,      // bn.bias   (beta)
  %arg2: tensor<6x6x7x7xf32> // input x
) -> tensor<6x6x7x7xf32> {
  // Compute mean over axes [0,2,3] (batch, H, W) for each channel
  // Input shape: [N=6, C=6, H=7, W=7]
  // Reduce over dims 0,2,3 -> output shape [6] (C)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce(%arg2, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %s : tensor<f32>
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Compute denominator for mean: N * H * W = 6*7*7 = 294
  %c294 = stablehlo.constant dense<294.0> : tensor<f32>
  %mean = stablehlo.divide %mean, %c294 : tensor<6xf32>

  // Broadcast mean to input shape for subtraction
  // mean shape: [6], input shape: [6,6,7,7], broadcast on dim 1
  %mean_bcast = stablehlo.broadcast_in_dim(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // x - mean
  %x_centered = stablehlo.subtract %arg2, %mean_bcast : tensor<6x6x7x7xf32>

  // Compute variance: mean((x - mean)^2) over [0,2,3]
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x6x7x7xf32>
  %var = stablehlo.reduce(%x_centered_sq, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %s : tensor<f32>
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>
  %var = stablehlo.divide %var, %c294 : tensor<6xf32>

  // Add epsilon for numerical stability (PyTorch default: 1e-5)
  %c_eps = stablehlo.constant dense<1.0000000116860974E-5> : tensor<f32>
  %var_eps = stablehlo.add %var, %c_eps : tensor<6xf32>

  // sqrt(var + eps)
  %std = stablehlo.sqrt %var_eps : tensor<6xf32>

  // Broadcast std to input shape for division
  %std_bcast = stablehlo.broadcast_in_dim(%std) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %x_norm = stablehlo.divide %x_centered, %std_bcast : tensor<6x6x7x7xf32>

  // Broadcast weight (gamma) and bias (beta) to input shape
  %weight_bcast = stablehlo.broadcast_in_dim(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>
  %bias_bcast = stablehlo.broadcast_in_dim(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // Output: y = x_norm * weight + bias
  %y = stablehlo.multiply %x_norm, %weight_bcast : tensor<6x6x7x7xf32>
  %y = stablehlo.add %y, %bias_bcast : tensor<6x6x7x7xf32>

  return %y : tensor<6x6x7x7xf32>
}

