module {
  func.func @main(
    %arg0: tensor<8x3x3x5x7xf32>,   // conv3d.weight: [out_channels, in_channels, kW, kH, kD]
    %arg1: tensor<16x3x8x8x8xf32>   // input: [batch, in_channels, width, height, depth]
  ) -> tensor<16x8x6x4x2xf32> {
    // PyTorch nn.Conv3d expects input [N, C_in, D, H, W] and weight [C_out, C_in, kD, kH, kW]
    // User's input: [N, C_in, W, H, D], weight: [C_out, C_in, kW, kH, kD]
    // We need to transpose input and weight to match PyTorch's expected layout.

    // Transpose input from [N, C_in, W, H, D] -> [N, C_in, D, H, W]
    %input_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 0, 1, 4, 3, 2>} : (tensor<16x3x8x8x8xf32>) -> tensor<16x3x8x8x8xf32>
    // Transpose weight from [C_out, C_in, kW, kH, kD] -> [C_out, C_in, kD, kH, kW]
    %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 0, 1, 4, 3, 2>} : (tensor<8x3x3x5x7xf32>) -> tensor<8x3x7x5x3xf32>

    // Now, input: [N, C_in, D, H, W], weight: [C_out, C_in, kD, kH, kW]
    // StableHLO expects input: [N, C_in, D, H, W], kernel: [C_out, C_in, kD, kH, kW]
    // Convolution attributes:
    // - window_strides = [1, 1, 1]
    // - padding = [ (0,0), (0,0), (0,0) ] (no padding)
    // - lhs_dilation = [1, 1, 1]
    // - rhs_dilation = [1, 1, 1]
    // - dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, o, 0, 1, 2]>
    // - feature_group_count = 1
    // - batch_group_count = 1

    // But the output shape is [16, 8, 6, 4, 2] (user expects [N, C_out, W_out, H_out, D_out])
    // PyTorch's output is [N, C_out, D_out, H_out, W_out], so we need to transpose back.

    // Calculate padding:
    // input spatial: D=8, H=8, W=8
    // kernel spatial: kD=7, kH=5, kW=3
    // stride=1, dilation=1, padding=0
    // Output spatial: floor((in + 2*pad - dilation*(k-1) - 1)/stride + 1)
    // D_out = floor((8 + 0 - 1*(7-1) - 1)/1 + 1) = floor((8 - 6 - 1) + 1) = floor(1 + 1) = 2
    // H_out = floor((8 + 0 - 1*(5-1) - 1)/1 + 1) = floor((8 - 4 - 1) + 1) = floor(3 + 1) = 4
    // W_out = floor((8 + 0 - 1*(3-1) - 1)/1 + 1) = floor((8 - 2 - 1) + 1) = floor(5 + 1) = 6
    // So output: [N, C_out, D_out, H_out, W_out] = [16, 8, 2, 4, 6]
