  // Compute mean over batch (dim 0): shape (7,)
  %zero_f32 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %mean = "stablehlo.reduce"(%gemm_bias, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // Divide by batch size (6)
  %six_f32 = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
  %mean = "stablehlo.divide"(%mean, %six_f32) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>
  // Broadcast mean to (6,7)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // x - mean
  %centered = "stablehlo.subtract"(%gemm_bias, %mean_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // (x - mean)^2
  %centered_sq = "stablehlo.multiply"(%centered, %centered) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Variance: mean of squared deviations over batch (dim 0)
  %var = "stablehlo.reduce"(%centered_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = "stablehlo.divide"(%var, %six_f32) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>
  // Add epsilon for numerical stability
  %eps = "stablehlo.constant"() {value = dense<1.0000000116860974E-5> : tensor<f32>} : () -> tensor<f32>
  %var_eps = "stablehlo.add"(%var, %eps) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>
  // sqrt(var + eps)
  %std = "stablehlo.sqrt"(%var_eps) : (tensor<7xf32>) -> tensor<7xf32>
  // Broadcast std to (6,7)
  %std_broadcast = "stablehlo.broadcast_in_dim"(%std) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // Normalize: (x - mean) / std
  %normed = "stablehlo.divide"(%centered, %std_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Broadcast gamma and beta to (6,7)
  %gamma_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %beta_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // Scale and shift: normed * gamma + beta
  %bn_scaled = "stablehlo.multiply"(%normed, %gamma_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %bn_out = "stablehlo.add"(%bn_scaled, %beta_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %sqrt2 = "stablehlo.constant"() {value = dense<1.4142135623730951> : tensor<f32>} : () -> tensor<f32>
  // x / sqrt(2)
  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %bn_div_sqrt2 = "stablehlo.divide"(%bn_out, %sqrt2_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // erf(x / sqrt(2))
  %erf = "chlo.erf"(%bn_div_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  // 1 + erf(...)
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %erf_plus_one = "stablehlo.add"(%one_broadcast, %erf) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // x * (1 + erf(...))
  %bn_times_erf = "stablehlo.multiply"(%bn_out, %erf_plus_one) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // 0.5 * x * (1 + erf(...))
  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %gelu = "stablehlo.multiply"(%half_broadcast, %bn_times_erf) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // ReLU: max(gelu, 0)
  %zero_broadcast =
